export const getTask=id=>TASKS.find(t=>t.id===id);
export function initialState(id,transfer=false){
 switch(id){case 'mic':return {muted:true,permission:!transfer,settings:false};case 'share':return {picker:false,surface:'',selected:false,sharing:false,stopped:false};case 'blur':return {effects:false,blur:false,applied:false};case 'pdf':return {exported:false,downloads:false,attached:false,sent:false};case 'access':return {audience:'group',viewed:false,confirmed:false};case 'form':return {email:'sana@',city:'',errors:false,submitted:false};case 'join':return {camera:true,muted:false,joined:false};case 'copy':return {choice:'',answer:'',checked:false};default:throw Error('Unknown task');}
}
export function isComplete(id,s){switch(id){case 'mic':return !s.muted&&s.permission;case 'share':return s.stopped&&s.selected&&s.surface==='window';case 'blur':return s.blur&&s.applied;case 'pdf':return s.sent;case 'access':return s.audience==='sana'&&s.viewed&&s.confirmed;case 'form':return s.submitted;case 'join':return s.joined;case 'copy':return s.choice==='file'&&s.answer==='keeps'&&s.checked;default:return false;}}
export function transition(id,state,action,value){const s={...state};
 switch(id){
 case 'mic':if(action==='mute')s.muted=!s.muted;if(action==='settings')s.settings=!s.settings;if(action==='permission')s.permission=!s.permission;break;
 case 'share':if(action==='picker')s.picker=true;if(action==='surface'){s.surface=value;s.selected=false;s.sharing=false;}if(action==='select'&&s.surface==='window')s.selected=true;if(action==='share'&&s.surface==='window'&&s.selected)s.sharing=true;if(action==='stop'&&s.sharing){s.sharing=false;s.stopped=true;}break;
 case 'blur':if(action==='effects')s.effects=true;if(action==='blur')s.blur=value==='blur';if(action==='apply'&&s.blur)s.applied=true;break;
 case 'pdf':if(action==='export'&&value==='pdf')s.exported=true;if(action==='downloads'&&s.exported)s.downloads=true;if(action==='attach'&&s.downloads)s.attached=true;if(action==='send'&&s.attached)s.sent=true;break;
 case 'access':if(action==='audience'){s.audience=value;s.viewed=false;s.confirmed=false;}if(action==='view')s.viewed=true;if(action==='confirm'&&s.viewed&&s.audience==='sana')s.confirmed=true;break;
 case 'form':if(action==='email')s.email=String(value).slice(0,100);if(action==='city')s.city=value;if(action==='submit'){s.errors=true;s.submitted=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)&&['Karachi','Lahore','Islamabad'].includes(s.city);}break;
 case 'join':if(action==='camera')s.camera=!s.camera;if(action==='mute')s.muted=!s.muted;if(action==='join'&&!s.camera&&s.muted)s.joined=true;break;
 case 'copy':if(action==='choice'){s.choice=value;s.checked=false;}if(action==='answer'){s.answer=value;s.checked=false;}if(action==='check')s.checked=true;break;
 }return s;
}
export function stage(id,s){if(isComplete(id,s))return 3;switch(id){case 'mic':return s.settings?1:0;case 'share':return s.sharing?2:s.picker?1:0;case 'blur':return s.blur?2:s.effects?1:0;case 'pdf':return s.attached?2:s.exported?1:0;case 'access':return s.viewed?2:s.audience==='sana'?1:0;case 'form':return s.errors?1:0;case 'join':return !s.camera&&s.muted?2:0;case 'copy':return s.choice==='file'?1:0;default:return 0;}}
export function searchTasks(query,category='All topics'){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);const ignored=new Set(['i','my','a','the','to','how','do','can','want','in','on','is','it','not','me','please','help','with','karna','hai','mujhe']);const terms=words.filter(w=>!ignored.has(w));return TASKS.filter(t=>category==='All topics'||t.category===category).map(t=>({t,score:terms.reduce((n,w)=>n+(`${t.title} ${t.description} ${t.tags} ${t.ur}`.toLowerCase().includes(w)?1:0),0)})).filter(x=>!terms.length||x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.t);}
